import { l, type L, type Class10Chapter, type ChapterVisual, type VisualStep } from './types';
import type { ChoiceTask, SelectTask, MatchTask, OrderTask, NumberTask, TaskBase } from '../lesson-content';

// Helpers share interface structure only; every teaching record below is authored.
const option = (id: string, en: string, hi: string, why: string, reason: string) => ({ id, label: l(en, hi), feedback: l(why, reason) });
const row = (id: string, en: string, hi: string, answer: string, why: string, reason: string) => ({ id, label: l(en, hi), answer, explanation: l(why, reason) });
const base = (prompt: L, context: L, hint: L): TaskBase => ({ prompt, context, hint,
  success: l('Your record meets these supplied checks. Keep the evidence and its limits together.', 'आपका रिकॉर्ड दी गई जाँच पूरी करता है। सबूत और उसकी सीमा साथ रखें।'),
  correction: l('Compare the named submitted items with the supplied rule and correct their specific reasons.', 'दिए आइटम को बताए नियम से मिलाएँ और बताए कारण के अनुसार सुधारें।'),
});
const choice = (b: TaskBase, options: ChoiceTask['options'], correct: string): ChoiceTask => ({ ...b, kind: 'choice', options, correct });
const select = (b: TaskBase, items: SelectTask['items'], expected: string[]): SelectTask => ({ ...b, kind: 'select', items, expected });
const match = (b: TaskBase, rows: MatchTask['rows'], options: MatchTask['options'], simulation?: MatchTask['simulation']): MatchTask => ({ ...b, kind: 'match', rows, options, ...(simulation ? { presentation: 'permissions' as const, simulation } : {}) });
const number = (b: TaskBase, fields: NumberTask['fields']): NumberTask => ({ ...b, kind: 'number', fields });
const order = (b: TaskBase, items: OrderTask['items'], expected: string[], stepReasons: L[]): OrderTask => ({ ...b, kind: 'order', items, expected, stepReasons });
const scene = (title: L, caption: L, dialogue: L) => ({ title, caption, dialogue });
const meta = (slug: string, title: L, summary: L, topics: [L,L,L], outcomes: [L,L,L], reflection: L, teacherPrompt: L) => ({
  slug, title, summary, strand: 'Cybersecurity' as const, topics, outcomes, reflection, teacherPrompt,
  familyAction: l('Draw this Decision Lab example with an adult using invented records. Explain one check and one uncertainty without opening a real account.', 'किसी बड़े के साथ काल्पनिक रिकॉर्ड लेकर यह डिसीजन लैब उदाहरण बनाएँ। असली खाता खोले बिना एक जाँच और एक अनिश्चितता समझाएँ।'),
  rubric: [l('Explain the supplied evidence and the boundary of its claim.', 'दिए सबूत और उसके दावे की सीमा समझाएँ।'), l('Complete the practical record and verify the stated checks.', 'व्यावहारिक रिकॉर्ड पूरा करके दी गई जाँच सत्यापित करें।'), l('Revise a decision and name what remains unresolved.', 'निर्णय सुधारें और अनसुलझी बात बताएँ।')] as [L,L,L],
});
type Frame = [string, number, number, string, string, string, string, 'active'|'warning'|'complete', string[]?];
const frame = ([id,x,y,en,hi,value,translation,status,edges]: Frame): VisualStep => ({
  label: l(en,hi), description: l(en,hi), active: [id], ...(status === 'warning' ? {warning:[id]} : status === 'complete' ? {complete:[id]} : {}),
  moves: [{id,x,y}], values: {[id]:l(value,translation)}, ...(edges ? {activeEdges:edges}:{}),
});
const visual = (layout: ChapterVisual['layout'], nodes: [string,string,string,number,number][], edges: [string,string,string][], plans: [Frame,Frame,Frame][], title: L, prompt: L, variants: [string,L,number,number][]): ChapterVisual => ({
  layout, nodes:nodes.map(([id,en,hi,x,y])=>({id,label:l(en,hi),x,y,shape:'card'})), edges:edges.map(([id,from,to])=>({id,from,to})),
  scenes: plans.map(steps=>({steps:steps.map(frame)})) as ChapterVisual['scenes'],
  exploration:{title,prompt,variants:variants.map(([id,label,scene,step])=>({id,label,scene,step}))},
});
const accessOptions = [{id:'deny',label:l('No access','एक्सेस बंद')},{id:'read',label:l('Read only','केवल पढ़ें')},{id:'edit',label:l('Read and edit','पढ़ें और एडिट करें')}];
const effect = (label: L, rowId: string, allowedAnswers: string[], allowed: L, denied: L) => ({label,checks:[{rowId,allowedAnswers}],allowed,denied});

